<div class="product-grid"><?php foreach($products as $i=>$product): ?><article class="product-card"><a class="product-image" href="products.php#<?= e($product['id']) ?>"><?php picture($product['image'],$product['name']); ?><span class="product-number">0<?= $i+1 ?></span></a><div class="product-info"><h3><?= e($product['name']) ?></h3><p><?= e($product['description']) ?></p><div class="product-links"><a class="text-link" href="products.php#<?= e($product['id']) ?>">اكتشف التفاصيل <?= icon('arrow') ?></a><?php booking('استفسر عنها','inquiry-link','مرحبًا رِقّة، أرغب بالاستفسار عن '.$product['name'].' لمناسبتي في تبوك.'); ?></div></div></article><?php endforeach; ?></div>
